export const dwspQualifier = /* @__PURE__ */ qualifierFn(B, DpQualifier.WIDTH, KIND_SP, false);
/** Density · alternate value above a dp threshold · text → device px. */
export const dwspQualifierPx = /* @__PURE__ */ qualifierFn(B, DpQualifier.WIDTH, KIND_SP, true);
/** Density · alternate value for UI mode + dp threshold · text → CSS px. */
export const dwspScreen = /* @__PURE__ */ screenFn(B, DpQualifier.WIDTH, KIND_SP, false);
