export const dwspScreenPx = /* @__PURE__ */ screenFn(B, DpQualifier.WIDTH, KIND_SP, true);

// ── Builder (Android `DimenDensity` / `DensitySp`). ───────────────────────────
/** Custom-dimension builder for the density strategy. */
export class DimenDensity extends DimenBuilder {
  get dsdp(): number { return this.sdp; }
  get dsdpPx(): number { return this.sdpPx; }
  get dssp(): number { return this.ssp; }
  get dsspPx(): number { return this.sspPx; }
  get dsem(): number { return this.sem; }
  get dsemPx(): number { return this.semPx; }
  get dhdp(): number { return this.hdp; }
  get dhdpPx(): number { return this.hdpPx; }
  get dhsp(): number { return this.hsp; }
  get dhspPx(): number { return this.hspPx; }
  get dhem(): number { return this.hem; }
  get dhemPx(): number { return this.hemPx; }
  get dwdp(): number { return this.wdp; }
  get dwdpPx(): number { return this.wdpPx; }
  get dwsp(): number { return this.wsp; }
  get dwspPx(): number { return this.wspPx; }
  get dwem(): number { return this.wem; }
  get dwemPx(): number { return this.wemPx; }
}
/** Starts a builder: `densityDp(16).screen(UiModeType.TELEVISION, 40).dsdp`. */
export const densityDp = (value: number): DimenDensity => new DimenDensity(B, value);
/** Text builder (same class; read `.dssp` / `.dsem`). */
export const densitySp = (value: number): DimenDensity => new DimenDensity(B, value);
